// Fluxos que chamam o Gemini. max_hora = execuções por hora acima do normal (= algo em loop).
// custo = R$ estimado por execução (para estimar o saldo). frear = pode ser desligado sozinho.
// As menções não estão aqui: o custo delas vem real da tabela "Zezinho - Consumo de IA".
const FLUXOS = [
  ['sXf86sWCWAIoXSc2', 'Zoom → ATA', 4, 0.20, true],
  ['0CQc4bAzQukc8rXC', 'Cartão Redacted (Conta Azul)', 15, 0.10, true],
  ['bd6cot6MpNovWKkz', 'Cartão Redacted Redacted Sicredi (Omie)', 15, 0.10, true],
  ['aygN6bOmhnLblszC', 'Cartão Redacted Redacted Caixa (Omie)', 15, 0.10, true],
  ['hXv7DXshDPjcaGXX', 'Cartão clientes Conta Azul Mais', 15, 0.10, true],
  // Agente (relatório das 17h): não dá para pausar sozinho; conta pela ferramenta que lê os chats.
  ['FbT6iViSXFWoi9xY', 'Agente Zezinho (relatório diário)', 6, 0.30, false],
];
return FLUXOS.map(f => ({ json: { id: f[0], nome: f[1], max_hora: f[2], custo: f[3], frear: f[4] } }));

// FREIO DE CUSTOS (sem IA). Cada aviso sai 1 vez só (memória do fluxo).
const COMPRA = { data: '2026-10-23T00:00:00-03:00', valor: 70 }; // atualizar quando comprar mais créditos
const AVISO_SALDO = [50, 63];          // R$ gastos (estimados) que geram aviso: ~70% e ~90%
const MENCOES_MAX_HORA = 15;           // chamadas ao Gemini das menções por hora (sem contar o provão)
const MENCOES_MAX_DIA = 5;             // R$ por dia (o teto normal é R$ 2,50)
const agora = Date.now();
const hoje = $now.setZone('America/Sao_Paulo').toFormat('yyyy-MM-dd');
const desde = new Date(COMPRA.data).getTime();
const st = $getWorkflowStaticData('global');
st.avisos = st.avisos || {};
const jaAvisou = k => st.avisos[k] === true;
const marcar = k => { st.avisos[k] = true; };
const acoes = [];
const fl = $('Fluxos com IA').all().map(i => i.json);
const resp = $('n8n - execuções recentes').all().map(i => i.json);
let estimado = 0;
fl.forEach((f, i) => {
  const ex = (resp[i] && resp[i].data) || [];
  const t = e => new Date(e.startedAt).getTime();
  const ultimaHora = ex.filter(e => agora - t(e) < 3600e3).length;
  const erros = ex.filter(e => (e.status === 'error' || e.status === 'crashed') && agora - t(e) < 16 * 60e3).length;
  estimado += ex.filter(e => t(e) >= desde && e.status !== 'canceled').length * f.custo;
  if (ultimaHora > f.max_hora && !jaAvisou('loop-' + f.id + '-' + hoje)) {
    marcar('loop-' + f.id + '-' + hoje);
    acoes.push(f.frear
      ? { acao: 'frear', id: f.id, titulo: '🛑 Freio de custos: desliguei ' + f.nome, texto: f.nome + ' rodou ' + ultimaHora + ' vezes na última hora (o normal é até ' + f.max_hora + '). Parece loop e cada execução gasta crédito do Gemini, então DESLIGUEI o fluxo. Para religar: abra o fluxo no n8n e clique em Publish depois de ver o que houve.' }
      : { acao: 'avisar', titulo: '⚠️ Freio de custos: ' + f.nome + ' acima do normal', texto: f.nome + ' rodou ' + ultimaHora + ' vezes na última hora (o normal é até ' + f.max_hora + '). O agente não é pausado sozinho: se continuar, desligue a tarefa no agente Gestor Contábil IA.' });
  }
  if (erros && !jaAvisou('erro-' + f.id + '-' + hoje)) {
    marcar('erro-' + f.id + '-' + hoje);
    acoes.push({ acao: 'avisar', titulo: '⚠️ ' + f.nome + ' deu erro', texto: f.nome + ' teve ' + erros + ' erro(s) nos últimos 15 min. Pode ser falta de saldo ou o teto de R$ ' + COMPRA.valor + ' do Gemini (AI Studio → Gasto/Faturamento). Veja a execução no n8n. (Aviso 1 vez por dia.)' });
  }
});
// Menções: custo real gravado pelo fluxo de menções. O provão (teste do TI, quem = 'Provão') entra no gasto, mas não conta como loop.
const linhas = $('Consumo das menções').all().map(i => i.json).filter(l => l.dia);
const reais = linhas.filter(l => l.origem === 'mencao' && l.quem !== 'Provão');
const mHora = reais.filter(l => agora - new Date(l.createdAt).getTime() < 3600e3).length;
const mHoje = reais.filter(l => l.dia === hoje).reduce((s, l) => s + (Number(l.custo_brl) || 0), 0);
estimado += linhas.filter(l => new Date(l.createdAt).getTime() >= desde).reduce((s, l) => s + (Number(l.custo_brl) || 0), 0);
if ((mHora > MENCOES_MAX_HORA || mHoje > MENCOES_MAX_DIA) && !jaAvisou('loop-mencoes-' + hoje)) {
  marcar('loop-mencoes-' + hoje);
  acoes.push({ acao: 'frear', id: 'mzuQpaZ7PSGfU8DB', titulo: '🛑 Freio de custos: desliguei as respostas às menções', texto: 'As menções fizeram ' + mHora + ' chamadas ao Gemini na última hora e gastaram R$ ' + mHoje.toFixed(2) + ' hoje (limites: ' + MENCOES_MAX_HORA + '/hora e R$ ' + MENCOES_MAX_DIA + '/dia). DESLIGUEI o fluxo "Zezinho · responder menções". As menções continuam guardadas na fila (o vigia segue rodando). Para religar: abra o fluxo e clique em Publish.' });
}
// Saldo estimado dos créditos
AVISO_SALDO.forEach(lim => {
  const k = 'saldo-' + COMPRA.data + '-' + lim;
  if (estimado >= lim && !jaAvisou(k)) {
    marcar(k);
    acoes.push({ acao: 'avisar', titulo: '💰 Créditos do Gemini acabando', texto: 'Gasto estimado desde ' + COMPRA.data.slice(0, 10) + ': R$ ' + estimado.toFixed(2) + ' de R$ ' + COMPRA.valor + '. Confira o saldo real no AI Studio → Faturamento e peça ao CEO para comprar mais créditos se precisar. Quando comprar, atualize COMPRA no fluxo "Zezinho · freio de custos".' });
  }
});
return acoes.map(a => ({ json: { ...a, estimado: Math.round(estimado * 100) / 100 } }));
